INSERT INTO `everlake_build_stage` (`n`, `ID`, `RewardText`) VALUES
(1, 94727, 'Ouch! Ouch! No more hit! What you want?'),
(2, 95417, '<The ogre lies dead, surrounded by a ring of dark runes. It appears to have been overwhelmed by the powers of the Twilight Hammer''s ritual.>'),
(3, 95418, 'Well, well. Looks like that cave was not our only surprise.$B$BYou managed to convince one of the Twilight''s Hammer ogres to defect? And he mentioned others of his kind? We must act on this immediately.'),
(4, 95427, 'Tiny skyborne kill Chogg''Zac?$B$B<Clubtoe lets out a triumphant bellow that echoes through the caves.>$B$BClubtoe done smashing rock for tinies! Clubtoe done losing friends! Me Twilight no more!'),
(5, 95601, 'Tiny skyborne not turn purple! Hurray!$B$BBut... where friends?'),
(6, 96103, '<Neza runs her fingers along the markings left on the skull. Her smile grows as she does so.>$B$BTwo pieces of good news. First, this is a human skull. Second, we have a great hunt on our hands.'),
(7, 97329, 'Is that the key?$B$B<Zimmix lunges forward against the front of the cage and he repeatedly attempts to swipe the key from your possession.>$B$BJust hand it over!'),
(8, 97331, 'Oh my gold. YOU were the one that rescued Zimmix?$B$BYour timing could not have been worse. We just had a celebratory toast thinking he was finally out of our hair for good, and we have another critical delivery coming up that has yet to be assigned. Of course, he''s already trying to claim it and, of course, I have to argue against it or we risk another one of his big blunders!$B$BWord of advice: If you see a goblin trapped in a cage, they probably deserve it. Just leave them there next time.')
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) SELECT p.`ID`, p.`RewardText`, 0 FROM `everlake_build_stage` p WHERE p.`free` = 1 ORDER BY p.`n`;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_offer_reward', p.`ID`, '2026_11_19_984_world_everlake_build.sql', s.`note` FROM `everlake_build_stage` p JOIN `everlake_build_quests` s ON s.`ID` = p.`ID` WHERE p.`free` = 1;
INSERT INTO `everlake_build_stage` (`n`, `ID`, `CompletionText`) VALUES
(1, 95418, 'So, the Twilight''s Hammer found something in the earth? You were right to banish this evil, $N. If it interests those fanatics, it''s not to be trusted.'),
(2, 95427, 'No more kill friends! Chogg''Zac die today!'),
(3, 96103, 'You bring something from the plains?'),
(4, 97329, 'Listen, I like you and all, but you standing around here is making us look suspicious! If you don''t have the key then, I dunno, GO GET IT!$B$BPlease?')
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) SELECT p.`ID`, p.`CompletionText`, 0 FROM `everlake_build_stage` p WHERE p.`free` = 1 ORDER BY p.`n`;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_request_items', p.`ID`, '2026_11_19_984_world_everlake_build.sql', s.`note` FROM `everlake_build_stage` p JOIN `everlake_build_quests` s ON s.`ID` = p.`ID` WHERE p.`free` = 1;
